export interface DateTime {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
}

export function date_time(year: number, month: number, day: number, hour: number, minute: number): DateTime {
  if (!Number.isInteger(year) || year < 1) throw new Error(`year must be int >= 1, got ${year}`);
  if (!Number.isInteger(month) || month < 1 || month > 12) throw new Error(`month must be 1..12, got ${month}`);
  if (!Number.isInteger(day) || day < 1 || day > 31) throw new Error(`day must be 1..31, got ${day}`);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23) throw new Error(`hour must be 0..23, got ${hour}`);
  if (!Number.isInteger(minute) || minute < 0 || minute > 59) throw new Error(`minute must be 0..59, got ${minute}`);
  return { year, month, day, hour, minute };
}

export function seed_off(): Record<string, any> {
  return { kind: "off", phi: 0, datetime: null };
}

export function seed_auto(phi: number = 0, datetime: DateTime | null = null): Record<string, any> {
  const res: Record<string, any> = { kind: "auto", phi };
  if (datetime !== null) {
    res.datetime = datetime;
  }
  return res;
}

export function seed_manual(datetime: DateTime, phi: number = 0): Record<string, any> {
  return { kind: "manual", phi, datetime };
}

export function int_value(n: number): Record<string, any> {
  return { Int: n };
}

export function float_value(n: number): Record<string, any> {
  return { Float: n };
}

export function date_ufo(seed: any): Record<string, any> {
  return { DateUFO: seed };
}

export function date_hfo(seed: any): Record<string, any> {
  return { DateHFO: seed };
}
